<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignamentRef;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Service\Visibility\UserRoleAssignamentVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignamentUpdateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignamentVisibilityService $visibility,
        private readonly UserRoleAssignamentWriteGateway $writer,
    ) {
    }

    public function allowUpdate(?UserRoleAssignamentRef $ref = null): Allow
    {
        $this->logDebug("Check allow update usecase for User role assignament");
        $span = $this->startSpan("Check allow update usecase for User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function fixedFields(?UserRoleAssignamentRef $ref = null): array
    {
        $this->logDebug("Check fixed fields for update usecase for User role assignament");
        $span = $this->startSpan("Check fixed fields for update usecase for User role assignament");
        try {
            return $this->visibility->fieldsToFix($ref);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function update(string $uid, UserRoleAssignamentUpdateParams $params): UserRoleAssignamentUpdateResult
    {
        $this->logDebug("Run update usecase for User role assignament");
        $span = $this->startSpan("Run update usecase for User role assignament");
        try {
            $ref = new UserRoleAssignamentRef($uid);
            $allow = $this->allowUpdate($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to update User role assignament');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new UserRoleAssignamentUpdateCheck($params, $original));
            $enriched = $this->dispatcher->dispatch(new UserRoleAssignamentUpdateEnrich($params, $original, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $modified = $original->update($input);
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserRoleAssignamentUpdateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
